+template <>
+__device__ __forceinline__ float4 load_state4<__half>(const __half* state) {
+  const __half2 lo = *reinterpret_cast<const __half2*>(state);
+  const __half2 hi = *reinterpret_cast<const __half2*>(state + 2);
